body:
Due to this bug of `HOME` env not being set, I wrote this C++ code to retrieve the home directory using the `pwd` API:

```cpp

#if __has_include(<pwd.h>) && __has_include(<unistd.h>) && __has_include(<sys/types.h>)
#include <pwd.h>
#include <sys/types.h>
#include <unistd.h>
#define HAS_PWD_H 1
#endif

#include <cstdlib>

namespace home {

using std::filesystem::path, std::filesystem::absolute, std::getenv, std::exception, std::runtime_error;

path home_dir() {
  // NOLINTNEXTLINE(concurrency-mt-unsafe) reading an unchanging environment variable
  auto home_dir = getenv("HOME");

  if (home_dir == nullptr) {
#if defined(HAS_PWD_H)
    // fallback to getpwuid

    // NOLINTNEXTLINE(concurrency-mt-unsafe) reading an unchanging variable
    home_dir = getpwuid(getuid())->pw_dir;
#else
    throw runtime_error("Failed to get the home directory");
#endif
  }
  return absolute(path(home_dir));
}

} // namespace home

```
